package com.example.bikerental; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; @Entity @Table(name="coupons") public class Coupon { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String code; @Column(nullable=false) private int discountPercent; private LocalDate expiryDate; @Column(nullable=false) private boolean active=true; public Coupon(){} public Coupon(String c,int d,LocalDate e){code=c;discountPercent=d;expiryDate=e;} public Long getId(){return id;} public String getCode(){return code;} public void setCode(String v){code=v;} public int getDiscountPercent(){return discountPercent;} public void setDiscountPercent(int v){discountPercent=v;} public LocalDate getExpiryDate(){return expiryDate;} public void setExpiryDate(LocalDate v){expiryDate=v;} public boolean isActive(){return active && (expiryDate==null || !expiryDate.isBefore(LocalDate.now()));} public void setActive(boolean v){active=v;} }